'use client'

import { useState } from 'react'
import { colors, spacing, typography, radius } from '@/lib/design-tokens'

/**
 * "Pay now" for an unpaid date generated by a truck's weekly hold (tester
 * OB-034, owner 2026-09-27: the truck's park-bookings list should offer the
 * payment, not only the booking page's Weekly hold tab). Same call the booking
 * form makes — POST /api/vendor/park-occurrences/[bookingId]/pay — which returns
 * a Stripe Checkout URL; the route owns every gate (ownership, hold still
 * active, date not past, same-day cutoff).
 */
export default function PayParkOccurrenceButton({ bookingId }: { bookingId: string }) {
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState<string | null>(null)

  async function go() {
    if (busy) return
    setBusy(true)
    setError(null)
    try {
      const res = await fetch(`/api/vendor/park-occurrences/${bookingId}/pay`, { method: 'POST' })
      const data = await res.json().catch(() => ({}))
      if (!res.ok) {
        setError(data.error || 'Could not start checkout. Please try again.')
        setBusy(false)
        return
      }
      if (typeof data.url === 'string' && data.url.length > 0) {
        window.location.href = data.url
        return
      }
      setError('Something went wrong setting up your payment. Please try again.')
    } catch {
      setError('Network error — please try again.')
    }
    setBusy(false)
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: spacing['2xs'], alignItems: 'flex-start' }}>
      <button
        type="button"
        onClick={go}
        disabled={busy}
        style={{ padding: `${spacing['2xs']} ${spacing.sm}`, backgroundColor: colors.primary, color: 'white', border: 'none', borderRadius: radius.sm, fontSize: typography.sizes.sm, fontWeight: typography.weights.semibold, cursor: busy ? 'not-allowed' : 'pointer', opacity: busy ? 0.6 : 1, whiteSpace: 'nowrap' }}
      >
        {busy ? 'Starting…' : 'Pay now'}
      </button>
      {error && (
        <span style={{ fontSize: typography.sizes.xs, color: '#991b1b', lineHeight: 1.4 }}>{error}</span>
      )}
    </div>
  )
}
